 10	// import { Octokit } from "@octokit/core";
 11	const { Octokit } = require("@octokit/core");
 12	import os from "os";
 13	
 14	dotenv.config();
 15	
 16	const execPromise = util.promisify(exec);
 17	
 18	type PublishConfig = {
 19	  version: string;
 20	  targetRepo: string;
 21	  releaseName?: string;
 22	};
 23	
 24	type ExecOptions = {
 25	  env?: Record<string, string>;
 26	  cwd?: string;
 27	};
