 29	const EXCLUDE_PATTERNS = [
 30	  "node_modules",
 31	  "dist",
 32	  ".env*",
 33	  ".turbo",
 34	  ".DS_Store",
 35	  "*.log",
 36	  "coverage",
 37	  ".next",
 38	  "out",
 39	  "build",
 40	  "scripts",
 41	  ".git",
 42	  ".vscode",
 43	  ".cursor",
 44	  "*.pem",
 45	  "temp-obsidian-publish",
 46	];
 47	
 48	const REQUIRED_BUILD_FILES = [
 49	  "main.js",
 50	  "manifest.json",
 51	  "styles.css",
 52	] as const;
 53	const BLOB_UPLOAD_BATCH_SIZE = 10;
 54	const MAX_GITHUB_RETRIES = 5;
 55	const BASE_RETRY_DELAY_MS = 2_000;
 56	
 57	const TARGET_REPO = "DiscourseGraphs/discourse-graph-obsidian";
 58	const OWNER = "DiscourseGraphs";
 59	const REPO = "discourse-graph-obsidian";
 60	
 61	const log = (message: string): void => {
 62	  console.log(`[Obsidian Publisher] ${message}`);
 63	};
 64	
 65	const sleep = async (ms: number): Promise<void> =>
 66	  new Promise((resolve) => setTimeout(resolve, ms));
 67	
 68	const isSecondaryRateLimitError = (error: unknown): boolean => {
 69	  const maybeError = error as {
 70	    status?: number;
 71	    response?: { data?: { message?: string } };
 72	    message?: string;
 73	  };
 74	  const message =
 75	    maybeError?.response?.data?.message?.toLowerCase() ??
 76	    maybeError?.message?.toLowerCase() ??
 77	    "";
 78	  return maybeError?.status === 403 && message.includes("secondary rate limit");
 79	};
 80	
 81	const getRetryDelayMs = (error: unknown, attempt: number): number => {
 82	  const maybeError = error as {
 83	    response?: { headers?: Record<string, string | undefined> };
 84	  };
 85	  const retryAfterHeader = maybeError?.response?.headers?.["retry-after"];
 86	  const retryAfterSeconds = Number(retryAfterHeader);
 87	  if (Number.isFinite(retryAfterSeconds) && retryAfterSeconds > 0) {
 88	    return retryAfterSeconds * 1000;
 89	  }
 90	  return BASE_RETRY_DELAY_MS * 2 ** attempt;
 91	};
 92	
 93	const requestWithRetry = async <T = unknown>(
 94	  request: () => Promise<T>,
 95	  context: string,
 96	): Promise<T> => {
 97	  let attempt = 0;
 98	
 99	  while (true) {
100	    try {
101	      return await request();
102	    } catch (error) {
103	      if (!isSecondaryRateLimitError(error) || attempt >= MAX_GITHUB_RETRIES) {
104	        throw error;
105	      }
106	
107	      const delayMs = getRetryDelayMs(error, attempt);
108	      log(
109	        `Secondary rate limit hit during ${context}. Retrying in ${Math.ceil(delayMs / 1000)}s (attempt ${attempt + 1}/${MAX_GITHUB_RETRIES})...`,
110	      );
111	      await sleep(delayMs);
112	      attempt += 1;
113	    }
114	  }
115	};
116	
117	const getAllFiles = (dir: string, baseDir: string = dir): string[] => {
118	  const files: string[] = [];
119	
120	  fs.readdirSync(dir, { withFileTypes: true }).forEach((entry) => {
121	    const fullPath = path.join(dir, entry.name);
122	    const relativePath = path.relative(baseDir, fullPath);
123	
124	    if (shouldExclude(fullPath, baseDir)) {
125	      log(`Excluding: ${relativePath}`);
126	      return;
127	    }
128	
129	    if (entry.isDirectory()) {
130	      files.push(...getAllFiles(fullPath, baseDir));
131	    } else {
132	      files.push(relativePath);
133	    }
134	  });
135	
136	  return files;
137	};
