139	const getGitBlobSha = (content: Buffer): string => {
140	  const header = Buffer.from(`blob ${content.length}\0`, "utf8");
141	  return crypto
142	    .createHash("sha1")
143	    .update(Buffer.concat([header, content]))
144	    .digest("hex");
145	};
146	
147	const chunk = <T>(items: T[], size: number): T[][] => {
148	  const chunks: T[][] = [];
149	  for (let i = 0; i < items.length; i += size) {
150	    chunks.push(items.slice(i, i + size));
151	  }
152	  return chunks;
153	};
