155	const getEnvVar = (name: string): string => {
156	  const value = process.env[name];
157	  if (!value) {
158	    throw new Error(`${name} environment variable is required`);
159	  }
160	  return value;
161	};
162	
163	const parseArgs = (): PublishConfig => {
164	  const args = process.argv.slice(2);
165	  const config: Partial<PublishConfig> = {
166	    targetRepo: TARGET_REPO,
167	  };
168	
169	  for (let i = 0; i < args.length; i++) {
170	    const arg = args[i];
171	    const nextArg = args[i + 1];
172	
173	    switch (arg) {
174	      case "--version":
175	      case "-v":
176	        if (!nextArg || nextArg.startsWith("-")) {
177	          throw new Error("Version argument is required after --version");
178	        }
179	        config.version = nextArg;
180	        i++;
181	        break;
182	      case "--release-name":
183	        if (!nextArg || nextArg.startsWith("-")) {
184	          throw new Error(
185	            "Release name argument is required after --release-name",
186	          );
187	        }
188	        config.releaseName = nextArg;
189	        i++;
190	        break;
191	      case "--help":
192	      case "-h":
193	        showHelp();
194	        process.exit(0);
195	    }
196	  }
197	
198	  if (!config.version) {
199	    throw new Error("Version is required. Use --version <version> or --help");
200	  }
201	
202	  validateVersion(config.version);
203	
204	  return config as PublishConfig;
205	};
206	
207	const validateVersion = (version: string): void => {
208	  const basicVersionPattern = /^\d+\.\d+\.\d+/;
209	
210	  if (!basicVersionPattern.test(version)) {
211	    throw new Error(
212	      `Invalid version format: ${version}. Expected format: x.y.z, x.y.z-suffix, or x.y.z-custom-name`,
213	    );
214	  }
215	};
216	
217	const isExternalRelease = (version: string): boolean => {
218	  // The Obsidian community store reads manifest.json from the publish repo's
219	  // main branch, so only a finished release may be external. Everything else
220	  // ships as a GitHub pre-release and leaves that branch untouched.
221	  const stablePattern = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/;
222	  if (stablePattern.test(version)) {
223	    return true;
224	  }
225	
226	  return false;
227	};
