229	const showHelp = (): void => {
230	  console.log(`
231	Usage: tsx scripts/publish-obsidian.ts --version <version> [options]
232	
233	Required:
234	  --version, -v <version>    Version to publish (see formats below)
235	
236	Options:
237	  --release-name <name>    Custom release name (defaults to "Discourse Graph v{version}")
238	  --help, -h               Show this help message
239	
240	Version Formats:
241	  x.y.z                    Stable release - auto-picked up by BRAT (e.g., 1.0.0)
242	  x.y.z-beta.n            Beta release - auto-picked up by BRAT (e.g., 1.0.0-beta.1)
243	  x.y.z-alpha-name        Internal release - manual install only (e.g., 0.1.0-alpha-canvas-feature)
244	
245	Release Type Auto-Detection:
246	  - External releases (stable, beta): Auto-updated by BRAT users
247	  - Internal releases (alpha prefix): Marked as pre-release, manual install only
248	
249	BRAT Version Priority:
250	  BRAT uses alphabetical ordering, so alpha < beta < stable
251	  - 0.1.0-alpha-feature (lowest priority)
252	  - 0.1.0-beta.1 (higher priority)
253	  - 0.1.0 (highest priority)
254	
255	Examples:
256	  # Internal release with custom name
257	  tsx scripts/publish-obsidian.ts --version 0.1.0-alpha-canvas --release-name "Canvas Integration Feature"
258	
259	  # Beta release with feature description
260	  tsx scripts/publish-obsidian.ts --version 1.0.0-beta.1 --release-name "Beta: New Graph View"
261	
262	  # Stable release (uses default name)
263	  tsx scripts/publish-obsidian.ts --version 1.0.0
264	`);
265	};
