267	const execCommand = async (
268	  command: string,
269	  options: ExecOptions = {},
270	): Promise<string> => {
271	  try {
272	    const { stdout, stderr } = await execPromise(command, {
273	      ...options,
274	      env: {
275	        ...process.env,
276	        ...options.env,
277	        GIT_ASKPASS: "echo",
278	        GIT_TERMINAL_PROMPT: "0",
279	      },
280	    });
281	
282	    log(`Command: ${command}`);
283	    log(`stdout: ${stdout.trim()}`);
284	    if (stderr) log(`stderr: ${stderr.trim()}`);
285	
286	    return stdout.trim();
287	  } catch (error) {
288	    const token = getEnvVar("OBSIDIAN_PLUGIN_REPO_TOKEN");
289	    if (token) {
290	      throw new Error((error as Error).message.replace(token, "***"));
291	    }
292	    throw error;
293	  }
294	};
