296	// Patterns match a whole path segment, never a substring of one, and globs are
297	// anchored to a single segment.
298	const segmentMatchesPattern = (segment: string, pattern: string): boolean => {
299	  if (!pattern.includes("*")) return segment === pattern;
300	
301	  const escaped = pattern
302	    .split("*")
303	    .map((part) => part.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"))
304	    .join("[^/]*");
305	  return new RegExp(`^${escaped}$`).test(segment);
306	};
307	
308	const shouldExclude = (filePath: string, baseDir: string): boolean => {
309	  const segments = path.relative(baseDir, filePath).split(path.sep);
310	  return segments.some((segment) =>
311	    EXCLUDE_PATTERNS.some((pattern) => segmentMatchesPattern(segment, pattern)),
312	  );
313	};
314	
315	const copyDirectory = ({
316	  src,
317	  dest,
318	  baseDir,
319	}: {
320	  src: string;
321	  dest: string;
322	  baseDir: string;
323	}): void => {
324	  if (!fs.existsSync(src)) {
325	    throw new Error(`Source directory does not exist: ${src}`);
326	  }
327	
328	  fs.mkdirSync(dest, { recursive: true });
329	
330	  fs.readdirSync(src, { withFileTypes: true }).forEach((entry) => {
331	    const srcPath = path.join(src, entry.name);
332	    const destPath = path.join(dest, entry.name);
333	
334	    if (shouldExclude(srcPath, baseDir)) {
335	      log(`Excluding: ${path.relative(baseDir, srcPath)}`);
336	      return;
337	    }
338	
339	    if (entry.isDirectory()) {
340	      copyDirectory({ src: srcPath, dest: destPath, baseDir });
341	    } else {
342	      try {
343	        fs.copyFileSync(srcPath, destPath);
344	      } catch (error) {
345	        throw new Error(`Failed to copy ${srcPath}: ${error}`);
346	      }
347	    }
348	  });
349	};
