351	const buildPlugin = async (dir: string): Promise<void> => {
352	  log("Building plugin...");
353	
354	  await execCommand("pnpm run build", { cwd: dir });
355	
356	  const buildDir = path.join(dir, "dist");
357	  const missingFiles = REQUIRED_BUILD_FILES.filter(
358	    (file) => !fs.existsSync(path.join(buildDir, file)),
359	  );
360	
361	  if (missingFiles.length > 0) {
362	    throw new Error(`Required build files missing: ${missingFiles.join(", ")}`);
363	  }
364	};
