366	const updateManifest = (tempDir: string, version: string): void => {
367	  const manifestPath = path.join(tempDir, "manifest.json");
368	  if (!fs.existsSync(manifestPath)) {
369	    throw new Error("manifest.json not found in temp directory");
370	  }
371	
372	  const manifest = JSON.parse(fs.readFileSync(manifestPath, "utf8"));
373	  manifest.version = version;
374	  manifest.id = "discourse-graphs";
375	
376	  fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2));
377	  log(`Updated manifest version to ${version}`);
378	};
