380	const copyBuildFiles = (buildDir: string, tempDir: string): void => {
381	  REQUIRED_BUILD_FILES.forEach((file) => {
382	    const srcPath = path.join(buildDir, file);
383	    if (fs.existsSync(srcPath)) {
384	      fs.copyFileSync(srcPath, path.join(tempDir, file));
385	      log(`Copied ${file}`);
386	    }
387	  });
388	};
