390	const installedVersion = (packageDir: string, name: string): string => {
391	  const pkgPath = path.join(packageDir, "node_modules", name, "package.json");
392	  if (!fs.existsSync(pkgPath)) {
393	    throw new Error(`Cannot resolve installed version of ${name}`);
394	  }
395	  return JSON.parse(fs.readFileSync(pkgPath, "utf8")).version;
396	};
397	
398	// Unpinned, vite's latest optional peers cycle back to a newer vitest and crash npm.
399	const vitestViteVersion = (obsidianDir: string): string => {
400	  const vitestDir = fs.realpathSync(
401	    path.join(obsidianDir, "node_modules", "vitest"),
402	  );
403	  return installedVersion(path.resolve(vitestDir, "../.."), "vite");
404	};
405	
406	// The community review runs npm install with no lockfile, so pnpm-only specifiers
407	// fail and open ranges drift into peer conflicts. Workspace packages are bundled.
408	const sanitizePackageJsonForMirror = (
409	  tempDir: string,
410	  obsidianDir: string,
411	): void => {
412	  const packageJsonPath = path.join(tempDir, "package.json");
413	  if (!fs.existsSync(packageJsonPath)) return;
414	
415	  const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, "utf8"));
416	  delete packageJson.scripts;
417	
418	  for (const field of ["dependencies", "devDependencies"]) {
419	    const deps: Record<string, string> | undefined = packageJson[field];
420	    if (!deps) continue;
421	    for (const [name, spec] of Object.entries(deps)) {
422	      if (spec.startsWith("workspace:")) {
423	        delete deps[name];
424	        log(`Removed workspace dependency ${name} from mirrored package.json`);
425	      } else {
426	        deps[name] = installedVersion(obsidianDir, name);
427	      }
428	    }
429	  }
430	  packageJson.overrides = { vite: vitestViteVersion(obsidianDir) };
431	
432	  fs.writeFileSync(packageJsonPath, JSON.stringify(packageJson, null, 2));
433	  log("Sanitized package.json for mirrored publish repo");
434	};
435	
436	// updateLocalVersion runs after the publish-repo push, so the release version
437	// has to be written into the staged copy here as well.
438	const updateStagedPackageVersion = (tempDir: string, version: string): void => {
439	  const packageJsonPath = path.join(tempDir, "package.json");
440	  if (!fs.existsSync(packageJsonPath)) return;
441	
442	  const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, "utf8"));
443	  packageJson.version = version;
444	  fs.writeFileSync(packageJsonPath, JSON.stringify(packageJson, null, 2));
445	  log(`Updated staged package.json version to ${version}`);
446	};
