448	const updateLocalVersion = (obsidianDir: string, version: string): void => {
449	  const packageJsonPath = path.join(obsidianDir, "package.json");
450	  const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, "utf8"));
451	  packageJson.version = version;
452	  fs.writeFileSync(
453	    packageJsonPath,
454	    JSON.stringify(packageJson, null, 2) + "\n",
455	  );
456	
457	  const manifestPath = path.join(obsidianDir, "manifest.json");
458	  const manifest = JSON.parse(fs.readFileSync(manifestPath, "utf8"));
459	  manifest.version = version;
460	  fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2) + "\n");
461	
462	  log(`Updated local package.json and manifest.json to version ${version}`);
463	};
