465	const updateMainBranch = async (
466	  tempDir: string,
467	  version: string,
468	): Promise<void> => {
469	  log(`Updating main branch of repository: ${TARGET_REPO}...`);
470	
471	  const token = getEnvVar("OBSIDIAN_PLUGIN_REPO_TOKEN");
472	  const octokit = new Octokit({ auth: token });
473	  const owner = OWNER;
474	  const repo = REPO;
475	
476	  try {
477	    const { data: ref } = await requestWithRetry<any>(
478	      () =>
479	        octokit.request("GET /repos/{owner}/{repo}/git/refs/{ref}", {
480	          owner,
481	          repo,
482	          ref: "heads/main",
483	        }),
484	      "fetching main branch ref",
485	    );
486	
487	    if (!ref?.object?.sha) {
488	      throw new Error("Failed to get main branch reference");
489	    }
490	    const currentSha = ref.object.sha;
491	
492	    const { data: currentCommit } = await requestWithRetry<any>(
493	      () =>
494	        octokit.request("GET /repos/{owner}/{repo}/git/commits/{commit_sha}", {
495	          owner,
496	          repo,
497	          commit_sha: currentSha,
498	        }),
499	      "fetching current main commit",
500	    );
501	
502	    if (!currentCommit?.tree?.sha) {
503	      throw new Error("Failed to get current commit tree");
504	    }
505	    const currentTreeSha = currentCommit.tree.sha;
506	    const { data: existingTree } = await requestWithRetry<any>(
507	      () =>
508	        octokit.request("GET /repos/{owner}/{repo}/git/trees/{tree_sha}", {
509	          owner,
510	          repo,
511	          tree_sha: currentTreeSha,
512	          recursive: "1",
513	        }),
514	      "fetching recursive main tree",
515	    );
516	
517	    const existingBlobShasByPath = new Map<string, string>(
518	      (existingTree.tree ?? [])
519	        .filter(
520	          (entry: any): entry is { path: string; sha: string; type: string } =>
521	            Boolean(entry.path && entry.sha && entry.type === "blob"),
522	        )
523	        .map((entry: { path: string; sha: string }) => [entry.path, entry.sha]),
524	    );
525	
526	    const allFiles = getAllFiles(tempDir);
527	    log(`Found ${allFiles.length} files to update`);
528	    const normalizedAllFiles = allFiles.map((filePath) =>
529	      filePath.replace(/\\/g, "/"),
530	    );
531	    const currentRepoFiles = new Set<string>(existingBlobShasByPath.keys());
532	    const localFiles = new Set<string>(normalizedAllFiles);
533	    const filesToDelete = [...currentRepoFiles].filter(
534	      (repoFilePath) => !localFiles.has(repoFilePath),
535	    );
536	    const filesToUpdate = allFiles.filter((filePath) => {
537	      const fullPath = path.join(tempDir, filePath);
538	      const content = fs.readFileSync(fullPath);
539	      const normalizedPath = filePath.replace(/\\/g, "/");
540	      const existingSha = existingBlobShasByPath.get(normalizedPath);
541	      return getGitBlobSha(content) !== existingSha;
542	    });
543	
544	    log(
545	      `Detected ${filesToUpdate.length} changed files (${allFiles.length - filesToUpdate.length} unchanged skipped)`,
546	    );
547	    log(`Detected ${filesToDelete.length} files to delete from target repo`);
548	
549	    if (filesToUpdate.length === 0 && filesToDelete.length === 0) {
550	      log("No changes detected on main branch; skipping commit update");
